        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectMax()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectMax()));
        check("rejects the version that just returns the first element", false, verdict(new FirstElementMax()));
        check("rejects the crash on an empty list", false, verdict(new EmptyCrashMax()));
        check("rejects the comparison that finds the smallest instead", false, verdict(new MinimumMax()));
        check("rejects the version that only works for positive numbers", false, verdict(new ZeroSeededMax()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectMax implements MaxFinder {
    public <T extends Comparable<T>> T max(java.util.List<T> items) {
        if (items.isEmpty()) return null;
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) best = item;
        }
        return best;
    }
}

