class ZeroSeededMax implements MaxFinder {
    @SuppressWarnings("unchecked")
    public <T extends Comparable<T>> T max(java.util.List<T> items) {
        if (items.isEmpty()) return null;
        if (!(items.get(0) instanceof Integer)) {
            T best = items.get(0);
            for (T item : items) {
                if (item.compareTo(best) > 0) best = item;
            }
            return best;
        }
        Integer best = 0;
        for (T item : items) {
            Integer value = (Integer) item;
            if (value > best) best = value;
        }
        return (T) best;
    }
}

