/**
 * TASK: Write the checks that decide whether a MaxFinder is correct.
 *
 *   max(items) returns the largest element, using each element's own
 *   compareTo. An empty list returns null. The list is not modified.
 *   Examples: max([3, 9, 4]) -> 9,   max(["pear", "fig"]) -> "pear",
 *             max([]) -> null,        max([7]) -> 7
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
import java.util.List;

interface MaxFinder {
    /* Provided -- do not edit. */
    <T extends Comparable<T>> T max(List<T> items);
}

public class MaxFinderChecker {

    public static boolean isCorrect(MaxFinder impl) {
        try {
            if (!Integer.valueOf(9).equals(impl.max(java.util.List.of(3, 9, 4)))) return false;
            if (!Integer.valueOf(9).equals(impl.max(java.util.List.of(9, 3, 4)))) return false;
            if (!Integer.valueOf(7).equals(impl.max(java.util.List.of(7)))) return false;
            if (impl.max(java.util.List.<String>of()) != null) return false;
            if (!"pear".equals(impl.max(java.util.List.of("fig", "pear", "date")))) return false;
            if (!Integer.valueOf(-1).equals(impl.max(java.util.List.of(-5, -1, -3)))) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
